<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_login();
require __DIR__.'/config/database.php';require_once __DIR__.'/date-widget.php';$bid=current_business_id();$notice='';$error='';$edit=null;
function baseq(array $p):float{return (float)$p['qty']*(float)$p['units_per_unit'];}
function sold(PDO $pdo,int $bid,int $pid):float{$q=$pdo->prepare("SELECT COALESCE(SUM(si.qty),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND si.product_id=? AND s.status='posted'");$q->execute([$bid,$pid]);return(float)$q->fetchColumn();}
function purchased(PDO $pdo,int $bid,int $pid,int $exclude=0):float{$sql='SELECT COALESCE(SUM(qty*units_per_unit),0) FROM purchases WHERE business_id=? AND product_id=?'.($exclude?' AND id<>?':'');$q=$pdo->prepare($sql);$a=[$bid,$pid];if($exclude)$a[]=$exclude;$q->execute($a);return(float)$q->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf((string)($_POST['csrf']??''))){$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
 try{if($action==='delete'&&$id){$q=$pdo->prepare('SELECT * FROM purchases WHERE id=? AND business_id=?');$q->execute([$id,$bid]);$old=$q->fetch();if(!$old)throw new RuntimeException('Purchase not found.');if(purchased($pdo,$bid,(int)$old['product_id'],$id)<sold($pdo,$bid,(int)$old['product_id']))throw new RuntimeException('Cannot delete: this would make stock negative because some units are already sold.');$q=$pdo->prepare('DELETE FROM purchases WHERE id=? AND business_id=?');$q->execute([$id,$bid]);$notice='Purchase deleted safely.';}
 else{$date=(string)($_POST['purchase_date']??'');$pid=(int)($_POST['product_id']??0);$sid=(int)($_POST['supplier_id']??0);$qty=(float)($_POST['qty']??0);$unit=(string)($_POST['purchase_unit']??'Piece');$conv=(float)($_POST['units_per_unit']??1);$rate=(float)($_POST['purchase_rate']??0);$discount=(float)($_POST['discount']??0);$transport=(float)($_POST['transport']??0);$tm=(string)($_POST['transport_mode']??'total');$other=(float)($_POST['other_cost']??0);$om=(string)($_POST['other_cost_mode']??'total');if(!$date||!$pid||!$sid||$qty<=0||$conv<=0||$rate<0)throw new RuntimeException('Date, Product, Supplier, Qty and conversion are required.');
  if($id){$q=$pdo->prepare('SELECT * FROM purchases WHERE id=? AND business_id=?');$q->execute([$id,$bid]);$old=$q->fetch();if(!$old)throw new RuntimeException('Purchase not found.');$oldPid=(int)$old['product_id'];if($oldPid!==$pid&&purchased($pdo,$bid,$oldPid,$id)<sold($pdo,$bid,$oldPid))throw new RuntimeException('Cannot move this purchase: old product stock would become negative.');if(purchased($pdo,$bid,$pid,$id)+($qty*$conv)<sold($pdo,$bid,$pid))throw new RuntimeException('Cannot save: purchased quantity would be below quantity already sold.');$q=$pdo->prepare('UPDATE purchases SET purchase_date=?,product_id=?,supplier_id=?,qty=?,purchase_unit=?,units_per_unit=?,purchase_rate=?,discount=?,transport=?,transport_mode=?,other_cost=?,other_cost_mode=? WHERE id=? AND business_id=?');$q->execute([$date,$pid,$sid,$qty,$unit,$conv,$rate,$discount,$transport,$tm,$other,$om,$id,$bid]);$notice='Purchase updated.';}
  else{$q=$pdo->prepare('INSERT INTO purchases(business_id,purchase_date,product_id,supplier_id,qty,purchase_unit,units_per_unit,purchase_rate,discount,transport,transport_mode,other_cost,other_cost_mode) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$bid,$date,$pid,$sid,$qty,$unit,$conv,$rate,$discount,$transport,$tm,$other,$om]);$notice='Purchase saved.';}}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Purchase could not be saved.';}}
elseif($_SERVER['REQUEST_METHOD']==='POST')$error='Session expired. Please try again.';
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM purchases WHERE id=? AND business_id=?');$q->execute([(int)$_GET['edit'],$bid]);$edit=$q->fetch()?:null;}
$q=$pdo->prepare('SELECT id,product_code,product_name FROM products WHERE business_id=? AND is_active=1 ORDER BY product_name');$q->execute([$bid]);$products=$q->fetchAll();$q=$pdo->prepare('SELECT id,supplier_code,supplier_name FROM suppliers WHERE business_id=? AND is_active=1 ORDER BY supplier_name');$q->execute([$bid]);$suppliers=$q->fetchAll();$q=$pdo->prepare('SELECT pu.*,p.product_code,p.product_name,s.supplier_code,s.supplier_name FROM purchases pu JOIN products p ON p.id=pu.product_id JOIN suppliers s ON s.id=pu.supplier_id WHERE pu.business_id=? ORDER BY pu.purchase_date DESC,pu.id DESC');$q->execute([$bid]);$rows=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchase Entry • MeroKhata</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/mero-date.css"><style>.msg{padding:10px;border-radius:8px;margin-bottom:12px}.ok{background:#ecfdf3;color:#166534}.err{background:#fff0f0;color:#991b1b}.smallbtn{padding:6px 9px;border:1px solid #ccd3dd;border-radius:6px;background:#fff;text-decoration:none;color:#223;font-size:12px}.accountbar{font-size:12px;margin-top:10px;padding-top:10px;border-top:1px solid #ffffff30}.accountbar a{color:#fff}</style></head><body><aside class="sidebar"><div class="brand">MeroKhata</div><div class="subbrand">Online Database</div><div class="nav"><button onclick="location.href='index.php'">Dashboard</button><button onclick="location.href='products.php'">Products</button><button onclick="location.href='suppliers.php'">Suppliers</button><button class="active">Purchase Entry</button><button>Party / Customer</button><button>Sales & Billing</button><button>Sales Register</button><button>Sales Reports</button><button>Stock / Inventory</button><button>Price Comparison</button></div><div class="accountbar"><?=htmlspecialchars($_SESSION['name']??'User')?> · <?=htmlspecialchars(ucfirst($_SESSION['role']??''))?><br><a href="logout.php">Logout</a></div></aside><main class="main"><div class="topbar"><h1>Purchase Entry</h1><div class="muted">MySQL Online</div></div><section class="panel active"><?php if($notice):?><div class="msg ok"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=htmlspecialchars($error)?></div><?php endif;?><div class="box"><h3><?=$edit?'Edit Purchase':'Add Purchase'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><input type="hidden" name="action" value="save"><div class="grid"><label>Date<?=mk_date_widget('purchase_date',(string)($edit['purchase_date']??''),'BS')?></label><label>Product<select name="product_id" required><option value="">Select Product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=($edit['product_id']??0)==$p['id']?'selected':''?>><?=htmlspecialchars($p['product_code'].' - '.$p['product_name'])?></option><?php endforeach;?></select></label><label>Supplier<select name="supplier_id" required><option value="">Select Supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>" <?=($edit['supplier_id']??0)==$s['id']?'selected':''?>><?=htmlspecialchars($s['supplier_code'].' - '.$s['supplier_name'])?></option><?php endforeach;?></select></label><label>Qty<input type="number" step="0.001" min="0.001" name="qty" required value="<?=htmlspecialchars((string)($edit['qty']??1))?>"></label><label>Purchase Unit<select name="purchase_unit"><?php foreach(['Piece','Dozen','Packet','Box','Ream','Set','Pair','Bundle'] as $u):?><option <?=($edit['purchase_unit']??'Piece')===$u?'selected':''?>><?=$u?></option><?php endforeach;?></select></label><label>Units per Unit<input type="number" step="0.001" min="0.001" name="units_per_unit" required value="<?=htmlspecialchars((string)($edit['units_per_unit']??1))?>"></label><label>Purchase Rate<input type="number" step="0.01" min="0" name="purchase_rate" required value="<?=htmlspecialchars((string)($edit['purchase_rate']??0))?>"></label><label>Discount<input type="number" step="0.01" min="0" name="discount" value="<?=htmlspecialchars((string)($edit['discount']??0))?>"></label><label>Transport<input type="number" step="0.01" min="0" name="transport" value="<?=htmlspecialchars((string)($edit['transport']??0))?>"></label><label>Transport Mode<select name="transport_mode"><option value="total" <?=($edit['transport_mode']??'total')==='total'?'selected':''?>>Total</option><option value="per_base" <?=($edit['transport_mode']??'')==='per_base'?'selected':''?>>Per Base Unit</option></select></label><label>Other Cost<input type="number" step="0.01" min="0" name="other_cost" value="<?=htmlspecialchars((string)($edit['other_cost']??0))?>"></label><label>Other Cost Mode<select name="other_cost_mode"><option value="total" <?=($edit['other_cost_mode']??'total')==='total'?'selected':''?>>Total</option><option value="per_base" <?=($edit['other_cost_mode']??'')==='per_base'?'selected':''?>>Per Base Unit</option></select></label></div><div class="actions"><button class="primary">Save Purchase</button><?php if($edit):?><button type="button" onclick="location.href='purchases.php'">Cancel Edit</button><?php endif;?></div></form></div><div class="box"><h3>Purchase Register</h3><table><thead><tr><th>Date</th><th>Product</th><th>Supplier</th><th>Qty</th><th>Unit</th><th>Base Qty</th><th>Rate</th><th>Actual Cost/Base</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):$b=(float)$r['qty']*(float)$r['units_per_unit'];$net=(float)$r['qty']*(float)$r['purchase_rate']-(float)$r['discount']+($r['transport_mode']==='per_base'?(float)$r['transport']*$b:(float)$r['transport'])+($r['other_cost_mode']==='per_base'?(float)$r['other_cost']*$b:(float)$r['other_cost']);?><tr><td><?=htmlspecialchars($r['purchase_date'])?></td><td><?=htmlspecialchars($r['product_code'].' - '.$r['product_name'])?></td><td><?=htmlspecialchars($r['supplier_code'].' - '.$r['supplier_name'])?></td><td><?=number_format((float)$r['qty'],3)?></td><td><?=htmlspecialchars($r['purchase_unit'])?> × <?=number_format((float)$r['units_per_unit'],3)?></td><td><?=number_format($b,3)?></td><td>Rs. <?=number_format((float)$r['purchase_rate'],2)?></td><td>Rs. <?=number_format($b?$net/$b:0,2)?></td><td><a class="smallbtn" href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this purchase?');"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="smallbtn">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main><script src="https://cdn.jsdelivr.net/npm/@remotemerge/nepali-date-converter@1/dist/ndc-browser.js"></script><script src="assets/js/mero-date.js"></script><script src="assets/js/online-nav.js"></script></body></html>